{
  "solutions": [
    {
      "id": "P9",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Chọn cặp (n_A, n_B) (có thể là số thực) thỏa mãn tải nhiệt $2160\\ \\mathrm{kJ}$ đồng thời không vượt quá thời gian tối đa $200\\ \\mathrm{s}$ và ngân sách điện $800\\ \\mathrm{kJ}$, với các thông số: mỗi chu trình A lấy $540\\ \\mathrm{kJ}$ nhiệt, tiêu thụ $180\\ \\mathrm{kJ}$ điện, mất $60\\ \\mathrm{s}$; mỗi chu trình B lấy $600\\ \\mathrm{kJ}$ nhiệt, tiêu thụ $240\\ \\mathrm{kJ}$ điện, mất $40\\ \\mathrm{s}$.",
      "solution": "Viết các bất đẳng thức ràng buộc:\\nTime: $60 n_A + 40 n_B \\le 200$.\\nEnergy: $180 n_A + 240 n_B \\le 800$.\\nHeat yêu cầu: $540 n_A + 600 n_B \\ge 2160$.\\nĐồ thị cho thấy điểm cực của miền khả thi là giao điểm của hai bất đẳng thức thời gian và năng lượng:\\n\\begin{cases}\\n60 n_A + 40 n_B = 200\\\\\\n180 n_A + 240 n_B = 800\\n\\end{cases}\\nGiải được $n_A = 20/9 \\approx 2.22$, $n_B = 5/3 \\approx 1.67$.\\nTại điểm này $Q = 540 n_A + 600 n_B = 2200\\ \\mathrm{kJ}$, thỏa mãn $Q \\ge 2160\\ \\mathrm{kJ}$. Do cả hai bất đẳng thức đều đạt giới hạn, cặp này là hợp lệ duy nhất trong các lựa chọn.",
      "claims": [
        {
          "text": "n_A = 20/9 chu trình, n_B = 5/3 chu trình",
          "correct": true,
          "misconception": null
        },
        {
          "text": "n_A = 3 chu trình, n_B = 0 chu trình",
          "correct": false,
          "misconception": "bỏ qua giới hạn thời gian"
        },
        {
          "text": "n_A = 0 chu trình, n_B = 3 chu trình",
          "correct": false,
          "misconception": "không đáp ứng yêu cầu nhiệt"
        },
        {
          "text": "n_A = 1 chu trình, n_B = 2 chu trình",
          "correct": false,
          "misconception": "không đáp ứng yêu cầu nhiệt"
        }
      ]
    },
    {
      "id": "P10",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Kết hợp công thức $COP = Q_c / W$ và các ràng buộc thời gian‑năng lượng để suy ra hệ số $COP$ tổng hợp của một hỗn hợp chu trình A và B; yêu cầu chọn tất cả các phát biểu đúng về $COP$ tổng hợp và ảnh hưởng của việc tăng tỉ lệ chu trình B.",
      "solution": "Đối với chế độ A: $COP_A = 540/180 = 3$.\\nĐối với chế độ B: $COP_B = 600/240 = 2.5$.\\nVới hỗn hợp, $Q_{\\text{tot}} = 540 n_A + 600 n_B$, $W_{\\text{tot}} = 180 n_A + 240 n_B$, do đó $COP_{\\text{hỗn}} = \\dfrac{540 n_A + 600 n_B}{180 n_A + 240 n_B}$.\\nVì $COP_B < COP_A$, khi tăng tỉ lệ $n_B/n_A$ thì tử số tăng ít hơn so với mẫu số, nên $COP_{\\text{hỗn}}$ giảm. Các phát biểu đúng được liệt kê dưới.",
      "claims": [
        {
          "text": "Nếu chỉ sử dụng chế độ A, hệ số COP tổng hợp bằng 3.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Nếu chỉ sử dụng chế độ B, hệ số COP tổng hợp bằng 2.5.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Khi tỉ lệ n_B/n_A tăng, hệ số COP tổng hợp tăng.",
          "correct": false,
          "misconception": "hiểu sai về ảnh hưởng của chu trình kém hiệu suất"
        },
        {
          "text": "Khi tỉ lệ n_B/n_A tăng, hệ số COP tổng hợp giảm.",
          "correct": true,
          "misconception": null
        }
      ]
    },
    {
      "id": "P11",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Giả sử thời gian hoạt động đạt đúng $200\\ \\mathrm{s}$, suy ra giới hạn tối đa của $n_A$ và $n_B$ từ bất đẳng thức thời gian, sau đó kết hợp với giới hạn ngân sách điện $800\\ \\mathrm{kJ}$ để tính lượng nhiệt tối đa $Q_{\\max}$ (kJ) có thể lấy được mà không vi phạm bất kỳ ràng buộc nào.",
      "solution": "Từ ràng buộc thời gian: $60 n_A + 40 n_B \\le 200 \\;\\Rightarrow\\; n_B = \\dfrac{200 - 60 n_A}{40}$.\\nThay vào bất đẳng thức năng lượng: $180 n_A + 240 n_B \\le 800$.\\nThay $n_B$ và giải được miền khả thi $0 \\le n_A \\le 20/9$.\\nHàm nhiệt $Q = 540 n_A + 600 n_B$ đạt cực đại tại giao điểm của hai bất đẳng thức, tức $n_A = 20/9$, $n_B = 5/3$.\\nKhi đó $Q_{\\max} = 540\\times\\frac{20}{9} + 600\\times\\frac{5}{3} = 1200 + 1000 = 2200\\ \\mathrm{kJ}$.",
      "answer": "2200 kJ",
      "claims": []
    },
    {
      "id": "P12",
      "verified": true,
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "question": "Có thể đạt tải nhiệt tối thiểu $2160\\ \\mathrm{kJ}$ mà không vượt quá thời gian $200\\ \\mathrm{s}$ và ngân sách điện $800\\ \\mathrm{kJ}$ không?",
      "solution": "Xây dựng miền khả thi từ hai bất đẳng thức: $60 n_A + 40 n_B \\le 200$ và $180 n_A + 240 n_B \\le 800$.\\nGiao điểm của chúng cho $n_A = 20/9$, $n_B = 5/3$ và $Q = 540 n_A + 600 n_B = 2200\\ \\mathrm{kJ}$.\\nVì $Q_{\\text{tối đa}} = 2200\\ \\mathrm{kJ} \\ge 2160\\ \\mathrm{kJ}$, nên tồn tại cặp $(n_A,n_B)$ thỏa mãn yêu cầu. Do đó câu trả lời là \"Có\".",
      "claims": [
        {
          "text": "Có, bằng cách chạy hỗn hợp với $n_A = 20/9$ và $n_B = 5/3$, cho $Q = 2200\\ \\mathrm{kJ}$.",
          "correct": true,
          "misconception": null
        },
        {
          "text": "Không, vì bất kỳ sự kết hợp nào đều không thể cung cấp đủ nhiệt do giới hạn năng lượng.",
          "correct": false,
          "misconception": "bỏ qua khả năng kết hợp thời gian và năng lượng"
        },
        {
          "text": "Không, vì thời gian tối đa $200\\ \\mathrm{s}$ không đủ cho ít nhất 4 chu trình của chế độ A.",
          "correct": false,
          "misconception": "đánh giá sai thời gian cần"
        },
        {
          "text": "Có, nhưng chỉ có thể đạt được nếu sử dụng hoàn toàn chế độ A và bỏ qua chế độ B.",
          "correct": false,
          "misconception": "không nhận ra giới hạn thời gian"
        }
      ]
    }
  ]
}
